import { createAstroSiteLoader } from "@lacecms/astro";

// Server-only: the loader reads LACE_BUILD_TOKEN. Astro dev revalidates the
// export on every request; a static build reads it once.
export const getSite = createAstroSiteLoader({
  env: { ...import.meta.env, ...process.env },
  dev: import.meta.env.DEV,
  hints: {
    missing_configuration:
      "Create a read-only build token in Admin Settings, set it in the ignored .env, and restart the site.",
    rejected_token:
      "Create or replace the read-only build token in Admin Settings, update the ignored .env, and restart the site.",
    api_unavailable: "Check that `pnpm dev:api` has started the API.",
  },
});

files.site/src/pages/blog/[slug].astro:
---
import LaceBlocks from "@lacecms/astro/LaceBlocks.astro";
import BaseLayout from "../../layouts/BaseLayout.astro";
import { blocks } from "../../lace/blocks";
import { getSite } from "../../lib/lace";

export async function getStaticPaths() {
  const site = await getSite();
  return site.entries("posts").map((entry) => ({ params: { slug: entry.slug } }));
}

// Read the current entry on each render so Astro dev shows publications on reload.
const site = await getSite();
const entry = site.bySlug("posts", Astro.params.slug ?? "");
if (entry === undefined) return new Response(null, { status: 404 });
---

<BaseLayout entry={entry} title={entry.title}>
  <LaceBlocks blocks={blocks} entry={entry} mediaUrl={site.mediaUrl} />
</BaseLayout>

